const hashToken=t=>createHash('sha256').update(t).digest('hex');
const issueToken=()=>randomBytes(32).toString('base64url');
const passwordHash=password=>{const salt=randomBytes(16).toString('hex');return `scrypt:${salt}:${scryptSync(password,salt,64).toString('hex')}`;};
const verifyPassword=(password,stored)=>{try{const [,salt,digest]=stored.split(':');const actual=scryptSync(password,salt,64),expected=Buffer.from(digest,'hex');return actual.length===expected.length&&timingSafeEqual(actual,expected);}catch{return false;}};
function cookies(req){return Object.fromEntries(String(req.headers.cookie||'').split(';').map(x=>x.trim().split('=').map(decodeURIComponent)).filter(x=>x.length===2));}
async function signedIn(req,p){const token=String(req.headers.authorization||'').replace(/^Bearer\s+/i,'')||cookies(req).kestrel_session;if(!token)return null;const r=await p.query('SELECT u.id,u.organization_id,u.email,u.full_name,u.status FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=$1 AND s.expires_at>now() AND u.status=$2',[hashToken(token),'active']);return r.rows[0]||null;}
function sendCookie(res,token){res.setHeader('Set-Cookie',`kestrel_session=${encodeURIComponent(token)}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=604800`);}
